// Иконка окна: 64x64 RGBA, сгенерировано tools/make_icon.py.
// Файл не правят руками - пересобирают скриптом.
use base64::{engine::general_purpose::STANDARD, Engine};

const RGBA_B64: &str = "";

pub const ICON_SIZE: u32 = 64;

pub fn rgba() -> Vec<u8> {
    STANDARD.decode(RGBA_B64).expect("иконка повреждена в исходниках")
}
